solution_code:
terraform {
  required_version = ">= 1.6.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "region" {
  type        = string
  description = "Région cloud utilisée par tout le projet"
  default     = "eu-west-3"
}

variable "plage_adresses" {
  type        = string
  description = "Plage CIDR du réseau principal"
  default     = "10.40.0.0/16"
}

variable "sous_reseaux" {
  type        = list(string)
  description = "Noms des sous-réseaux à créer"
  default     = ["app", "bdd"]
}

provider "aws" {
  region = var.region
}

resource "aws_vpc" "principal" {
  cidr_block = var.plage_adresses

  tags = {
    Nom       = "vpc-principal"
    Projet    = "exercice-do-c5"
    Environnement = "apprentissage"
  }
}

resource "aws_subnet" "prive" {
  for_each          = toset(var.sous_reseaux)
  vpc_id            = aws_vpc.principal.id
  cidr_block        = "10.40.${index(var.sous_reseaux, each.value)}.0/24"
  availability_zone = "${var.region}a"

  tags = {
    Nom    = each.value
    Projet = "exercice-do-c5"
  }
}

resource "aws_instance" "application" {
  ami           = "ami-0c55b159cbfafe1f0"
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.prive["app"].id

  tags = {
    Nom    = "application"
    Projet = "exercice-do-c5"
  }
}

output "adresse_publique" {
  description = "Adresse publique de la machine d'application"
  value       = aws_instance.application.public_ip
  sensitive   = true
}
